const url = 'https://www.mongodb.com/docs/vector-search/tutorials/quick-start/?deployment-type=atlas&interface=atlas-ui&embedding=auto';
const res = await fetch(url, { redirect: 'follow' });
const text = await res.text();
const chars = [...text].length;
const last50 = [...text].slice(-50).join('');
const estimatedTokens = Math.round(chars / 4);
console.log(JSON.stringify({ status: res.status, finalUrl: res.url, chars, estimatedTokens, last50, contentType: res.headers.get('content-type'), contentLength: res.headers.get('content-length') }));
